export async function listTools() {
  return [
    {
      name: 'user_note',
      description: 'Store a note for a user',
      inputSchema: {
        type: 'object',
        properties: {
          user_id: { type: 'string' },
          note: { anyOf: [{ type: 'string' }, { type: 'null' }] }
        },
        required: ['user_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'user_note') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32602;
    throw err;
  }
  // Validate args is object
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    const err = new Error('Invalid arguments');
    err.code = -32602;
    throw err;
  }
  const { user_id, note, ...rest } = args;
  // extra fields
  const keys = Object.keys(rest);
  if (keys.length > 0) {
    const err = new Error('Unexpected field: ' + keys[0]);
    err.code = -32602;
    throw err;
  }
  // user_id required string
  if (typeof user_id !== 'string') {
    const err = new Error('user_id must be a string');
    err.code = -32602;
    throw err;
  }
  // note: if present must be string or null
  let resolvedNote = null;
  if ('note' in args) {
    if (args.note === null) {
      resolvedNote = null;
    } else if (typeof args.note === 'string') {
      resolvedNote = args.note;
    } else {
      const err = new Error('note must be a string or null');
      err.code = -32602;
      throw err;
    }
  }
  return {
    content: [{ type: 'text', text: JSON.stringify({ user_id, note: resolvedNote }) }]
  };
}
```

